@Test
public void thatFileObjectCanBeInjected() throws Exception {
    FileInjection target = new FileInjection();
    initialize(target, "file", new File("test"), "fileFromString", "test", "fileArray", new File[] { new File("test1"), new File("test2") }, "fileArrayFromString", new String[] { "test1", "test2" }, "fileList", asList(new File("test1"), new File("test2")), "fileSet", unmodifiableSet(new File("test1"), new File("test2")), "fileFromStringList", asList("test1", "test2"));
    assertThat(target.file).hasName("test");
    assertThat(target.fileFromString).hasName("test");
    assertThat(target.fileArray).extracting(File::getName).containsExactly("test1", "test2");
    assertThat(target.fileArrayFromString).extracting(File::getName).containsExactly("test1", "test2");
    assertThat(target.fileList).extracting(File::getName).containsExactly("test1", "test2");
    assertThat(target.fileFromStringList).extracting(File::getName).containsExactly("test1", "test2");
    assertThat(target.fileSet).extracting(File::getName).containsExactlyInAnyOrder("test1", "test2");
}

@Test
public void thatClassObjectCanBeInjected() throws Exception {
    ClassInjection target = new ClassInjection();
    initialize(target, "clazz", Integer.class, "clazzFromString", Integer.class.getName(), "clazzArray", new Class<?>[] { Integer.class, Boolean.class, Float.class }, "clazzArrayFromString", new String[] { Integer.class.getName(), Boolean.class.getName(), Float.class.getName() }, "clazzList", asList(Integer.class, Boolean.class, Float.class), "clazzListFromString", asList(Integer.class.getName(), Boolean.class.getName(), Float.class.getName()), "clazzSet", unmodifiableSet(Integer.class, Boolean.class, Float.class));
    assertThat(target.clazz).isEqualTo(Integer.class);
    assertThat(target.clazzFromString).isEqualTo(Integer.class);
    assertThat(target.clazzArray).containsExactly(Integer.class, Boolean.class, Float.class);
    assertThat(target.clazzArrayFromString).containsExactly(Integer.class, Boolean.class, Float.class);
    assertThat(target.clazzList).containsExactly(Integer.class, Boolean.class, Float.class);
