public void testAAEMultipleDeploymentPolicy() throws Exception {
    {
        AnalysisEngineDescription desc1 = AnalysisEngineFactory.createEngineDescription(PristineAnnotatorClass.class, (Object[]) null);
        assertThat(desc1.getAnalysisEngineMetaData().getOperationalProperties().isMultipleDeploymentAllowed()).as("Multiple deployment should be allowed on " + desc1.getAnnotatorImplementationName()).isTrue();
        AnalysisEngineDescription desc2 = createEngineDescription(UnannotatedAnnotatorClass.class, (Object[]) null);
