        UIMAFramework.produceAnalysisEngine(aae);
        assertThat(aae.getAnalysisEngineMetaData().getOperationalProperties().//
        isMultipleDeploymentAllowed()).as("Multiple deployment should be prohibited on AAE").isFalse();
