@Test
public void testXReader() throws UIMAException, IOException {
    ResourceInitializationException rie = null;
    try {
        CollectionReaderFactory.createReader(SingleFileXReader.class, null, SingleFileXReader.PARAM_XML_SCHEME, "XML");
    } catch (ResourceInitializationException e) {
        rie = e;
    }
    assertThat(rie).isNotNull();
    rie = null;
    try {
        CollectionReaderFactory.createReader(SingleFileXReader.class, null, SingleFileXReader.PARAM_XML_SCHEME, "XML", SingleFileXReader.PARAM_FILE_NAME, "myxslt.xml");
    } catch (ResourceInitializationException e) {
        rie = e;
    }
    assertThat(rie).isNotNull();
    CollectionReader cr = CollectionReaderFactory.createReader(SingleFileXReader.class, typeSystemDescription, SingleFileXReader.PARAM_XML_SCHEME, "XCAS", SingleFileXReader.PARAM_FILE_NAME, "src/test/resources/data/docs/test.xcas");
    Progress[] progress = cr.getProgress();
    assertThat(progress).hasSize(1);
    assertThat(progress[0].getCompleted()).isEqualTo(0);
    assertThat(cr.hasNext()).isTrue();
    new JCasIterator(cr).next();
    progress = cr.getProgress();
    assertThat(progress).hasSize(1);
    assertThat(progress[0].getCompleted()).isEqualTo(1);
    cr.close();
    cr = CollectionReaderFactory.createReader(SingleFileXReader.class, typeSystemDescription, SingleFileXReader.PARAM_XML_SCHEME, "XCAS", SingleFileXReader.PARAM_FILE_NAME, "test/data/docs/test.xcas");
    UnsupportedOperationException uoe = null;
    try {
        new JCasIterator(cr).remove();
    } catch (UnsupportedOperationException e) {
        uoe = e;
    }
    assertThat(uoe).isNotNull();
    cr.close();
    HideOutput hideOutput = new HideOutput();
    cr = CollectionReaderFactory.createReader(SingleFileXReader.class, typeSystemDescription, SingleFileXReader.PARAM_XML_SCHEME, "XCAS", SingleFileXReader.PARAM_FILE_NAME, "test/data/docs/bad.xcas");
    RuntimeException re = null;
    try {
        new JCasIterator(cr).next();
    } catch (RuntimeException e) {
        re = e;
    }
    assertThat(re).isNotNull();
    hideOutput.restoreOutput();
    cr = CollectionReaderFactory.createReader(SingleFileXReader.class, typeSystemDescription, SingleFileXReader.PARAM_XML_SCHEME, "XMI", SingleFileXReader.PARAM_FILE_NAME, "test/data/docs/dne.xmi");
    re = null;
    try {
        JCasIterator jCases = new JCasIterator(cr);
        assertThat(jCases.hasNext()).isTrue();
        jCases.next();
    } catch (RuntimeException e) {
        re = e;
    }
    assertThat(re).isNotNull();
}

