        assertThat(TestAnnotator.lastDocument).isEqualTo("new test");
        assertThat(TestAnnotator2.lastDocument).isEqualTo("new test");
        cas.reset();
    } catch (Exception e) {
        JUnitExtension.handleException(e);
    }
