    try {
        // create aggregate analysis engine whose delegates each declare
        // type system, type priorities, and indexes
        var in = new XMLInputSource(JUnitExtension.getFile("TextAnalysisEngineImplTest/AggregateTaeForMergeTest.xml"));
        var desc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(in);
        var ae = new AggregateAnalysisEngine_impl();
        ae.initialize(desc, Collections.EMPTY_MAP);
        // initialize method automatically calls processDelegateAnalysisEngineMetaData()
        // test results of merge
        // TypeSystem
        var typeSys = ae.getAnalysisEngineMetaData().getTypeSystem();
        assertThat(typeSys.getTypes()).hasSize(8);
        var type0 = typeSys.getType("NamedEntity");
        assertThat(type0).isNotNull();
        assertThat(type0.getSupertypeName()).isEqualTo(CAS.TYPE_NAME_ANNOTATION);
        assertThat(type0.getFeatures()).hasSize(1);
        var type1 = typeSys.getType("Person");
        assertThat(type1).isNotNull();
        assertThat(type1.getSupertypeName()).isEqualTo("NamedEntity");
        assertThat(type1.getFeatures()).hasSize(1);
        var type2 = typeSys.getType("Place");
        assertThat(type2).isNotNull();
        assertThat(type2.getSupertypeName()).isEqualTo("NamedEntity");
        assertThat(type2.getFeatures()).hasSize(3);
        var type3 = typeSys.getType("Org");
        assertThat(type3).isNotNull();
        assertThat(type3.getSupertypeName()).isEqualTo(CAS.TYPE_NAME_ANNOTATION);
        assertThat(type3.getFeatures()).isEmpty();
        var type4 = typeSys.getType("DocumentStructure");
        assertThat(type4).isNotNull();
        assertThat(type4.getSupertypeName()).isEqualTo(CAS.TYPE_NAME_ANNOTATION);
        assertThat(type4.getFeatures()).isEmpty();
        var type5 = typeSys.getType("Paragraph");
        assertThat(type5).isNotNull();
        assertThat(type5.getSupertypeName()).isEqualTo("DocumentStructure");
        assertThat(type5.getFeatures()).isEmpty();
        var type6 = typeSys.getType("Sentence");
        assertThat(type6).isNotNull();
        assertThat(type6.getSupertypeName()).isEqualTo("DocumentStructure");
        assertThat(type6.getFeatures()).isEmpty();
        var type7 = typeSys.getType("test.flowController.Test");
        assertThat(type7).isNotNull();
        assertThat(type7.getSupertypeName()).isEqualTo(CAS.TYPE_NAME_ANNOTATION);
        assertThat(type7.getFeatures()).hasSize(1);
        // TypePriorities
        var pri = ae.getAnalysisEngineMetaData().getTypePriorities();
        assertThat(pri).isNotNull();
        var priLists = pri.getPriorityLists();
        assertThat(priLists).hasSize(3);
        var list0 = priLists[0].getTypes();
        var list1 = priLists[1].getTypes();
        var list2 = priLists[2].getTypes();
        // order of the three lists is not defined
        assertThat((list0.length == 2 && list1.length == 2 && list2.length == 3) || (list0.length == 2 && list1.length == 3 && list2.length == 2) || (list0.length == 3 && list1.length == 2 && list2.length == 2)).isTrue();
        // Indexes
        var indexes = ae.getAnalysisEngineMetaData().getFsIndexes();
        assertThat(indexes).hasSize(3);
        // order of indexes is not defined
        var label0 = indexes[0].getLabel();
        var label1 = indexes[1].getLabel();
        var label2 = indexes[2].getLabel();
        assertThat(label0.equals("DocStructIndex") || label1.equals("DocStructIndex") || label2.equals("DocStructIndex")).isTrue();
        assertThat(label0.equals("PlaceIndex") || label1.equals("PlaceIndex") || label2.equals("PlaceIndex")).isTrue();
        assertThat(label0.equals("FlowControllerTestIndex") || label1.equals("FlowControllerTestIndex") || label2.equals("FlowControllerTestIndex")).isTrue();
        // test that we can create a CAS
        var cas = ae.newCAS();
        var ts = cas.getTypeSystem();
        assertThat(ts.getType("NamedEntity")).isNotNull();
        assertThat(ts.getType("Person")).isNotNull();
        assertThat(ts.getType("Place")).isNotNull();
        assertThat(ts.getType("Org")).isNotNull();
        assertThat(ts.getType("DocumentStructure")).isNotNull();
        assertThat(ts.getType("Paragraph")).isNotNull();
        assertThat(ts.getType("Sentence")).isNotNull();
        assertThat(ts.getType("test.flowController.Test")).isNotNull();
    } catch (Exception e) {
        JUnitExtension.handleException(e);
    }
}

