@Test
void testProcessAndOutputNewCASesWithError() throws Exception {
    // aggregate
    var aggSegDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(JUnitExtension.getFile("TextAnalysisEngineImplTest/AggregateWithSegmenterForErrorTest.xml")));
    var ae = UIMAFramework.produceAnalysisEngine(aggSegDesc);
    var cas = ae.newCAS();
    for (// verify we can do this more than once
    var i = 0; // verify we can do this more than once
    i < 2; // verify we can do this more than once
    i++) {
        FlowControllerForErrorTest.reset();
        cas.setDocumentText("Line one\nLine two\nERROR");
        var iter = ae.processAndOutputNewCASes(cas);
        assertThat(iter.hasNext()).isTrue();
        var outCas = iter.next();
        assertThat(outCas.getDocumentText()).isEqualTo("Line one");
        outCas.release();
        assertThat(iter.hasNext()).isTrue();
        outCas = iter.next();
        assertThat(outCas.getDocumentText()).isEqualTo("Line two");
        outCas.release();
        try {
            // Suppress logging of expected exception
            UIMAFramework.getLogger().setLevel(Level.OFF);
            assertThat(iter.hasNext()).isTrue();
            outCas = iter.next();
            // the above should throw an exception
            fail();
        } catch (Exception e) {
        } finally {
            // Restore to apparent default of INFO
            UIMAFramework.getLogger().setLevel(Level.INFO);
        }
        // check that FlowController was notified twice, once for the
        // segment's flow and once for the complete document's flow
        assertThat(FlowControllerForErrorTest.abortedDocuments).hasSize(2);
        assertThat(FlowControllerForErrorTest.abortedDocuments).contains("ERROR");
        assertThat(FlowControllerForErrorTest.abortedDocuments).contains("Line one\nLine two\nERROR");
        cas.reset();
    }
    // nested aggregate
    var nestedAggSegDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(JUnitExtension.getFile("TextAnalysisEngineImplTest/NestedAggregateSegmenterForErrorTest.xml")));
    ae = UIMAFramework.produceAnalysisEngine(nestedAggSegDesc);
    cas = ae.newCAS();
    for (// verify we can do this more than once
    var i = 0; // verify we can do this more than once
    i < 2; // verify we can do this more than once
    i++) {
        FlowControllerForErrorTest.reset();
        cas.setDocumentText("Line one\nLine two\nERROR");
        var iter = ae.processAndOutputNewCASes(cas);
        assertThat(iter.hasNext()).isTrue();
        var outCas = iter.next();
        assertThat(outCas.getDocumentText()).isEqualTo("Line one");
        outCas.release();
        assertThat(iter.hasNext()).isTrue();
        outCas = iter.next();
        assertThat(outCas.getDocumentText()).isEqualTo("Line two");
        outCas.release();
        try {
            // Suppress logging of expected exception
            UIMAFramework.getLogger().setLevel(Level.OFF);
            assertThat(iter.hasNext()).isTrue();
            outCas = iter.next();
            // the above should throw an exception
            fail();
        } catch (Exception e) {
        } finally {
            UIMAFramework.getLogger().setLevel(Level.INFO);
        }
        // check that FlowController was notified three times, once for the
        // segment's flow and twice for the complete document's flow (once
        // in each aggregate)
        assertThat(FlowControllerForErrorTest.abortedDocuments).hasSize(3);
        assertThat(FlowControllerForErrorTest.abortedDocuments).contains("ERROR");
        assertThat(FlowControllerForErrorTest.abortedDocuments).contains("Line one\nLine two\nERROR");
        FlowControllerForErrorTest.abortedDocuments.remove("Line one\nLine two\nERROR");
        assertThat(FlowControllerForErrorTest.abortedDocuments).contains("Line one\nLine two\nERROR");
        cas.reset();
    }
    // 2 segmenters
    var twoSegDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(JUnitExtension.getFile("TextAnalysisEngineImplTest/AggregateWith2SegmentersForErrorTest.xml")));
    ae = UIMAFramework.produceAnalysisEngine(twoSegDesc);
    cas = ae.newCAS();
    for (// verify we can do this more than once
    var i = 0; // verify we can do this more than once
    i < 2; // verify we can do this more than once
    i++) {
        FlowControllerForErrorTest.abortedDocuments.clear();
        cas.setDocumentText("One\tTwo\nThree\tERROR");
        var iter = ae.processAndOutputNewCASes(cas);
        assertThat(iter.hasNext()).isTrue();
        var outCas = iter.next();
        assertThat(outCas.getDocumentText()).isEqualTo("One");
        outCas.release();
        assertThat(iter.hasNext()).isTrue();
        outCas = iter.next();
        assertThat(outCas.getDocumentText()).isEqualTo("Two");
        outCas.release();
        assertThat(iter.hasNext()).isTrue();
        outCas = iter.next();
        assertThat(outCas.getDocumentText()).isEqualTo("Three");
        outCas.release();
        try {
            // Suppress logging of expected exception
            UIMAFramework.getLogger().setLevel(Level.OFF);
            assertThat(iter.hasNext()).isTrue();
            outCas = iter.next();
            // the above should throw an exception
            fail();
        } catch (Exception e) {
        } finally {
            // Restore to apparent default of INFO
            UIMAFramework.getLogger().setLevel(Level.INFO);
        }
        // check that FlowController was notified three times, once for each level of granularity
        assertThat(FlowControllerForErrorTest.abortedDocuments).hasSize(3);
        assertThat(FlowControllerForErrorTest.abortedDocuments).contains("ERROR");
        assertThat(FlowControllerForErrorTest.abortedDocuments).contains("Three\tERROR");
        assertThat(FlowControllerForErrorTest.abortedDocuments).contains("One\tTwo\nThree\tERROR");
        cas.reset();
    }
    // segmenter that requests too many CASes
    var segmenterDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(JUnitExtension.getFile("TextAnalysisEngineImplTest/BadSegmenter.xml")));
    ae = UIMAFramework.produceAnalysisEngine(segmenterDesc);
    cas = ae.newCAS();
    cas.setDocumentText("Line one\nLine two\nLine three");
    var iter = ae.processAndOutputNewCASes(cas);
    assertThat(iter.hasNext()).isTrue();
    // first call OK
    var outCas = iter.next();
    outCas.release();
    assertThat(iter.hasNext()).isTrue();
    // next call should fail with AnalysisEngineProcessException
    try {
        // Suppress logging of expected exception
        UIMAFramework.getLogger().setLevel(Level.OFF);
        iter.next();
        // should not get here
        fail();
    } catch (Exception e) {
    } finally {
        // Restore to apparent default of INFO
        UIMAFramework.getLogger().setLevel(Level.INFO);
    }
    // bad segmenter in an aggregate
    var aggWithBadSegmenterDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(JUnitExtension.getFile("TextAnalysisEngineImplTest/AggregateWithBadSegmenterForErrorTest.xml")));
    ae = UIMAFramework.produceAnalysisEngine(aggWithBadSegmenterDesc);
    FlowControllerForErrorTest.reset();
    cas = ae.newCAS();
    cas.setDocumentText("Line one\nLine two\nLine three");
    iter = ae.processAndOutputNewCASes(cas);
    assertThat(iter.hasNext()).isTrue();
    // first call OK
    outCas = iter.next();
    outCas.release();
    assertThat(FlowControllerForErrorTest.abortedDocuments).isEmpty();
    assertThat(FlowControllerForErrorTest.failedAEs).isEmpty();
    // next call should fail with AnalysisEngineProcessException
    try {
        // Suppress logging of expected exception
        UIMAFramework.getLogger().setLevel(Level.OFF);
        if (iter.hasNext()) {
            iter.next();
        }
        // should not get here
        fail();
    } catch (Exception e) {
    } finally {
        // Restore to apparent default of INFO
        UIMAFramework.getLogger().setLevel(Level.INFO);
    }
    assertThat(FlowControllerForErrorTest.abortedDocuments).hasSize(1).contains("Line one\nLine two\nLine three");
    assertThat(FlowControllerForErrorTest.failedAEs).hasSize(1).contains("Segmenter");
    // configure AE to continue after error
    ae = UIMAFramework.produceAnalysisEngine(aggWithBadSegmenterDesc);
    ae.setConfigParameterValue("ContinueOnFailure", Boolean.TRUE);
    ae.reconfigure();
    FlowControllerForErrorTest.reset();
    cas.reset();
    cas.setDocumentText("Line one\nLine two\nLine three");
    iter = ae.processAndOutputNewCASes(cas);
    assertThat(iter.hasNext()).isTrue();
    // first call OK
    outCas = iter.next();
    outCas.release();
    assertThat(FlowControllerForErrorTest.abortedDocuments).isEmpty();
    assertThat(FlowControllerForErrorTest.failedAEs).isEmpty();
    // next call should not have aborted, but FC should have been notified of the failiure,
    // and no CAS should come back
    // Suppress logging of expected exception
    UIMAFramework.getLogger().setLevel(Level.OFF);
    try {
        assertThat(iter.hasNext()).isFalse();
    } finally {
        // Restore to apparent default of INFO
        UIMAFramework.getLogger().setLevel(Level.INFO);
    }
    assertThat(FlowControllerForErrorTest.abortedDocuments).isEmpty();
    assertThat(FlowControllerForErrorTest.failedAEs).hasSize(1).contains("Segmenter");
}

