    var sdiType = inputCas1.getTypeSystem().getType("org.apache.uima.examples.SourceDocumentInformation");
    var uriFeat = sdiType.getFeatureByBaseName("uri");
    inputCas1.setDocumentText("This is");
    var sdiFS = inputCas1.createFS(sdiType);
    sdiFS.setStringValue(uriFeat, "cas1");
    inputCas1.getIndexRepository().addFS(sdiFS);
    var inputCas2 = ae.newCAS();
    inputCas2.setDocumentText(" one.\nThis is");
    var sdiFS2 = inputCas2.createFS(sdiType);
    sdiFS2.setStringValue(uriFeat, "cas2");
    inputCas2.getIndexRepository().addFS(sdiFS2);
    var inputCas3 = ae.newCAS();
    inputCas3.setDocumentText(" two.\n");
    var sdiFS3 = inputCas3.createFS(sdiType);
    sdiFS3.setStringValue(uriFeat, "cas3");
    inputCas3.getIndexRepository().addFS(sdiFS3);
    // input first CAS. Should be no segments yet.
    var iter = ae.processAndOutputNewCASes(inputCas1);
    assertThat(iter.hasNext()).isFalse();
    // input second CAS. We should get back one segment.
    iter = ae.processAndOutputNewCASes(inputCas2);
    assertThat(iter.hasNext()).isTrue();
    var outCas = iter.next();
    var outJCas = outCas.getJCas();
    assertThat(outCas.getDocumentText()).isEqualTo("This is one.");
    // -- check SourceDocumentInformation FSs
    AnnotationIndex<SourceDocumentInformation> ai = outCas.getAnnotationIndex(sdiType);
    Iterator<SourceDocumentInformation> sdiIter = ai.iterator();
    Iterator<SourceDocumentInformation> sdiIter2 = outCas.<SourceDocumentInformation>getAnnotationIndex(sdiType).iterator();
    var ai2 = outJCas.getAnnotationIndex(SourceDocumentInformation.class);
    Iterator<SourceDocumentInformation> sdiIter3 = outJCas.getAnnotationIndex(SourceDocumentInformation.class).iterator();
    // testing to see if these compile OK
    for (var sdi : ai) {
    }
    for (var sdi : outCas.<SourceDocumentInformation>getAnnotationIndex(sdiType)) {
    }
    assertThat(sdiIter.hasNext()).isTrue();
    AnnotationFS outSdiFs = sdiIter.next();
    assertThat(outSdiFs.getCoveredText()).isEqualTo("This is");
    assertThat(outSdiFs.getStringValue(uriFeat)).isEqualTo("cas1");
    assertThat(sdiIter.hasNext()).isTrue();
    outSdiFs = sdiIter.next();
    assertThat(outSdiFs.getCoveredText()).isEqualTo(" one.");
    assertThat(outSdiFs.getStringValue(uriFeat)).isEqualTo("cas2");
    assertThat(sdiIter.hasNext()).isFalse();
    // --
    assertThat(iter.hasNext()).isFalse();
    // input third CAS. We should get back one more segment.
    iter = ae.processAndOutputNewCASes(inputCas3);
    assertThat(iter.hasNext()).isTrue();
    outCas = iter.next();
    outJCas = outCas.getJCas();
    assertThat(outCas.getDocumentText()).isEqualTo("This is two.");
    // -- check SourceDocumentInformation FSs
    sdiIter = outCas.<SourceDocumentInformation>getAnnotationIndex(sdiType).iterator();
    assertThat(sdiIter.hasNext()).isTrue();
    outSdiFs = sdiIter.next();
    assertThat(outSdiFs.getCoveredText()).isEqualTo("This is");
    assertThat(outSdiFs.getStringValue(uriFeat)).isEqualTo("cas2");
    assertThat(sdiIter.hasNext()).isTrue();
    outSdiFs = sdiIter.next();
    assertThat(outSdiFs.getCoveredText()).isEqualTo(" two.");
    assertThat(outSdiFs.getStringValue(uriFeat)).isEqualTo("cas3");
    assertThat(sdiIter.hasNext()).isFalse();
    // --
    assertThat(iter.hasNext()).isFalse();
}

@Test
void testProcessWithError() throws Exception {
    // This test uses an aggregate AE fails if the document text is set to "ERROR".
    var aeDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(JUnitExtension.getFile("TextAnalysisEngineImplTest/AggregateForErrorTest.xml")));
    var ae = UIMAFramework.produceAnalysisEngine(aeDesc);
    FlowControllerForErrorTest.reset();
    var cas = ae.newCAS();
    // try document that should succeed
    cas.setDocumentText("This is OK");
    ae.process(cas);
    // flow controller should not be notified
    assertThat(FlowControllerForErrorTest.abortedDocuments).isEmpty();
    assertThat(FlowControllerForErrorTest.failedAEs).isEmpty();
    // now one that fails
    cas.reset();
    cas.setDocumentText("ERROR");
    try {
        // Suppress logging of expected exception
        UIMAFramework.getLogger().setLevel(Level.OFF);
        ae.process(cas);
        fail();
    } catch (Exception e) {
    } finally {
        // Restore to apparent default of INFO
        UIMAFramework.getLogger().setLevel(Level.INFO);
    }
    assertThat(FlowControllerForErrorTest.abortedDocuments).hasSize(1).contains("ERROR");
    assertThat(FlowControllerForErrorTest.failedAEs).hasSize(1).contains("ErrorAnnotator");
    // AE should still be able to process a new document now
    FlowControllerForErrorTest.reset();
    cas.reset();
    cas.setDocumentText("This is OK");
    ae.process(cas);
    assertThat(FlowControllerForErrorTest.abortedDocuments).isEmpty();
    assertThat(FlowControllerForErrorTest.failedAEs).isEmpty();
    // configure AE to continue after error
    ae.setConfigParameterValue("ContinueOnFailure", Boolean.TRUE);
    ae.reconfigure();
    cas.reset();
    cas.setDocumentText("ERROR");
    // Suppress logging of expected exception
    UIMAFramework.getLogger().setLevel(Level.OFF);
    try {
        // should not throw exception now
        ae.process(cas);
    } finally {
        // Restore to apparent default of INFO
        UIMAFramework.getLogger().setLevel(Level.INFO);
    }
    // document should not have aborted, but FC should have been notified of the failure
    assertThat(FlowControllerForErrorTest.abortedDocuments).isEmpty();
    assertThat(FlowControllerForErrorTest.failedAEs).hasSize(1).contains("ErrorAnnotator");
}

@Test
void testThrottleLogging() throws Exception {
    // This test uses an aggregate AE fails if the document text is set to "ERROR".
    var aeDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(JUnitExtension.getFile("TextAnalysisEngineImplTest/AggregateForErrorTest.xml")));
    var ae = UIMAFramework.produceAnalysisEngine(aeDesc);
    FlowControllerForErrorTest.reset();
    var cas = ae.newCAS();
    for (var i = 0; i < 2; i++) {
        cas.setDocumentText("LOG");
        try {
            ae.process(cas);
        } catch (AnalysisEngineProcessException e) {
            fail();
        }
        cas.reset();
    }
    System.err.println("should see 2 WARN loggings above");
    ae = UIMAFramework.produceAnalysisEngine(aeDesc, Collections.singletonMap(AnalysisEngine.PARAM_THROTTLE_EXCESSIVE_ANNOTATOR_LOGGING, 1));
    FlowControllerForErrorTest.reset();
    cas = ae.newCAS();
    for (var i = 0; i < 2; i++) {
        cas.setDocumentText("LOG");
        try {
            ae.process(cas);
        } catch (AnalysisEngineProcessException e) {
            fail();
        }
        cas.reset();
    }
    System.err.println("should see 1 WARN logging above");
    ae = UIMAFramework.produceAnalysisEngine(aeDesc, Collections.singletonMap(AnalysisEngine.PARAM_THROTTLE_EXCESSIVE_ANNOTATOR_LOGGING, 0));
    FlowControllerForErrorTest.reset();
    cas = ae.newCAS();
    for (var i = 0; i < 2; i++) {
        cas.setDocumentText("LOG");
        try {
            ae.process(cas);
        } catch (AnalysisEngineProcessException e) {
            fail();
        }
        cas.reset();
    }
    System.err.println("should see no logging above");
}

