@Test
public void testFeatInheritance() {
    check(tofT1allFeat, K.Contains, f1);
    check(tofT1, K.NotContain, f1);
    check(tofF1, K.Contains, f1);
    check(tofT2, K.NotContain, f1);
    check(tofT2allFeat, K.Contains, f2);
    check(tofT2, K.NotContain, f2);
    // because allFeat on T1 doesn't include F2 which is only
    check(tofT1allFeat, K.NotContain, f2);
    // introduced on T2
    // feature spec'd for subtype
    check(tofT2F1, K.NotContain, f1);
    check(tofT2F1, K.Contains, "T2:F1");
    // oops, features not inheriting
    check(tofT2F1, K.Contains, "T3:F1");
    // because allFeat on T1 doesn't include F4 which is only
    check(tofT1allFeat, K.NotContain, f4);
    // introduced on T4
    check(tofT2allFeat, K.NotContain, f4);
    check(tofT1, K.NotContain, f4);
}

