public void testXMLization() throws Exception {
    try {
        // write objects to XML
        StringWriter writer = new StringWriter();
        primitiveDesc.toXML(writer);
        String primitiveDescXml = writer.getBuffer().toString();
        // System.out.println(primitiveDescXml);
        writer = new StringWriter();
        aggregateDesc.toXML(writer);
        String aggregateDescXml = writer.getBuffer().toString();
        // System.out.println(aggregateDescXml);
        // parse objects back from XML
        InputStream is = new ByteArrayInputStream(primitiveDescXml.getBytes(UTF_8));
        AnalysisEngineDescription newPrimitiveDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(is, null));
        is = new ByteArrayInputStream(aggregateDescXml.getBytes(UTF_8));
        AnalysisEngineDescription newAggregateDesc = UIMAFramework.getXMLParser().parseAnalysisEngineDescription(new XMLInputSource(is, null));
        assertThat(newPrimitiveDesc).isEqualTo(primitiveDesc);
        assertThat(newAggregateDesc).isEqualTo(aggregateDesc);
    } catch (Exception e) {
        JUnitExtension.handleException(e);
    }
}

// Note: This test case requires an input directory that has
// 1) a file typesystem.xml which has the type system for the serialized files
// 2) a bunch of files having compressed serialized CASes
// Set the directory in the 2nd line below
@Test
void testBinaryCasDeserialization6Performance() throws Exception {
    File dir = new File("");
    if (!dir.exists()) {
        return;
    }
    File typeSystemFile = new File(dir, "typesystem.xml");
    XMLInputSource in = new XMLInputSource(typeSystemFile);
    TypeSystemDescription typeSystemDescription = UIMAFramework.getXMLParser().parseTypeSystemDescription(in);
    CAS cas = CasCreationUtils.createCas(typeSystemDescription, null, null);
    long accumDeser = 0;
    long accumSer = 0;
    for (int i = 0; i < 10; i++) {
        for (final File f : dir.listFiles()) {
            if (f.getName().equals("typesystem.xml")) {
                continue;
            }
            InputStream inputStream = new BufferedInputStream(new FileInputStream(f));
            cas.reset();
            long ist = System.nanoTime();
            Serialization.deserializeCAS(cas, inputStream);
            accumDeser += System.nanoTime() - ist;
            ByteArrayOutputStream baos = new ByteArrayOutputStream(1024 * 512);
            ist = System.nanoTime();
            Serialization.serializeWithCompression(cas, baos, cas.getTypeSystem());
            accumSer += System.nanoTime() - ist;
            // System.out.format("Time to deserialize was %,d milliseconds, size = %d%n",
            // (System.nanoTime() - ist) / 1000000L, ((CASImpl)cas).getHeap().getHeapSize());
        }
    }
    // (System.nanoTime() - startTime) / 1000000L);
    System.out.format("Time to deserialize all files was %,d milliseconds%n", accumDeser / 1000000);
    System.out.format("Time to serialize   all files was %,d milliseconds%n", accumSer / 1000000);
}

@Test
void testCasReleaseNotAllowed() throws Exception {
    final Properties p = new Properties();
    p.put(UIMAFramework.CAS_INITIAL_HEAP_SIZE, 200);
    casManager.defineCasPool("id", 2, p);
    CASImpl c = (CASImpl) casManager.getCas("id");
    c.setCasState(CasState.UIMA_AS_WAIT_4_RESPONSE);
    Exception ex = null;
    try {
        c.release();
    } catch (UIMARuntimeException e) {
        ex = e;
    }
    assertThat(ex != null && ex.getMessage().equals("Illegal invocation of casRelease() while awaiting response from a UIMA-AS Service.")).isTrue();
    c.clearCasState(CasState.UIMA_AS_WAIT_4_RESPONSE);
    assertThatNoException().isThrownBy(() -> c.release());
}

