@Test
void testMetaspaceExhaustion() throws Exception {
    var threshold = 2_500;
    var classLoadingMXBean = ManagementFactory.getClassLoadingMXBean();
    var classesLoadedAtStart = classLoadingMXBean.getLoadedClassCount();
    var type = tsd.addType(Sentence._TypeName, "", CAS.TYPE_NAME_ANNOTATION);
    type.addFeature(Sentence._FeatName_sentenceLength, null, CAS.TYPE_NAME_INTEGER);
    LOG.info("Metaspace exhaustion test starting - this may take a while...");
    var startTime = currentTimeMillis();
    var target = threshold * 2;
    var loadedClasses = classLoadingMXBean.getLoadedClassCount();
    for (var i = 0; i < threshold * 2; i++) {
        if ((i + 1) % 250 == 0) {
            var duration = currentTimeMillis() - startTime;
            LOG.info("Metaspace exhaustion test - progress: {} / {} -- {}ms per CAS - {} classes", i + 1, target, duration / i + 1, (loadedClasses - classesLoadedAtStart));
        }
        var resMgr = new ResourceManager_impl();
        resMgr.setExtensionClassPath(".", false);
        createCas(tsd, null, null, null, resMgr).getJCas();
        System.runFinalization();
        // Make sure the consolidated type system is evicted from the weak hashmap cache
        System.gc();
        loadedClasses = classLoadingMXBean.getLoadedClassCount();
        //
        assertThat(loadedClasses).as("High number of new loaded classes during test indicates leak").isLessThan(classesLoadedAtStart + threshold);
    }
    LOG.info("Classes accumulated during test: {}", classLoadingMXBean.getLoadedClassCount() - classesLoadedAtStart);
    var duration = currentTimeMillis() - startTime;
    LOG.info("Metaspace exhaustion test finished in {}ms ({}ms per CAS)", duration, duration / target);
}

