void testv1FormatXcas() throws Exception {
    var cas = CasCreationUtils.createCas(typeSystem, new TypePriorities_impl(), FsIndexDescription.EMPTY_FS_INDEX_DESCRIPTIONS);
    var ts = cas.getTypeSystem();
    var v1cas = CasCreationUtils.createCas(ts, new TypePriorities_impl(), FsIndexDescription.EMPTY_FS_INDEX_DESCRIPTIONS, null);
