    xmlReader.parse(new InputSource(serCasStream));
    serCasStream.close();
    // compare
    assertThat(v1cas.getAnnotationIndex().size()).isEqualTo(cas.getAnnotationIndex().size());
    assertThat(CAS.NAME_DEFAULT_SOFA.equals(v1cas.getSofa().getSofaID())).isTrue();
