@Test
void testOutOfTypeSystemDataComplexCas() throws Exception {
    // deserialize a complex XCAS
    var originalCas = CasCreationUtils.createCas(typeSystem, null, indexes);
    InputStream serCasStream = new FileInputStream(JUnitExtension.getFile("ExampleCas/cas.xml"));
    XCASDeserializer.deserialize(serCasStream, originalCas);
    serCasStream.close();
    // serialize to XMI
    var xmiStr = serialize(originalCas, null);
    // deserialize into a CAS with no type system
    var casWithNoTs = CasCreationUtils.createCas(new TypeSystemDescription_impl(), new TypePriorities_impl(), FsIndexDescription.EMPTY_FS_INDEX_DESCRIPTIONS);
    var sharedData = new XmiSerializationSharedData();
    deserialize(xmiStr, casWithNoTs, sharedData, true, -1);
    // now reserialize including OutOfTypeSystem data
    var xmiStr2 = serialize(casWithNoTs, sharedData);
    // deserialize into a new CAS that has the full type system
    var newCas = CasCreationUtils.createCas(typeSystem, null, indexes);
    deserialize(xmiStr2, newCas, null, false, -1);
    // compare
    CasComparer.assertEquals(originalCas, newCas);
    // Test a partial type system with a missing some missing features and
    // missing "Organization" type
    var partialTypeSystemFile = JUnitExtension.getFile("ExampleCas/partialTestTypeSystem.xml");
    var partialTypeSystem = UIMAFramework.getXMLParser().parseTypeSystemDescription(new XMLInputSource(partialTypeSystemFile));
    var partialTsCas = CasCreationUtils.createCas(partialTypeSystem, null, indexes);
    var sharedData2 = new XmiSerializationSharedData();
    deserialize(xmiStr, partialTsCas, sharedData2, true, -1);
    var xmiStr3 = serialize(partialTsCas, sharedData2);
    newCas.reset();
    deserialize(xmiStr3, newCas, null, false, -1);
    CasComparer.assertEquals(originalCas, newCas);
}

@Test
void testInvalidCharsInDocumentText() throws Exception {
    CAS cas = CasCreationUtils.createCas(typeSystemDesc, null, null);
    char badChar = 0x1A;
    cas.setDocumentText("Text with bad char: " + badChar);
    OutputStream out = new FileOutputStream(outputFile);
    XMLSerializer xmlSerializer = new XMLSerializer(out);
    XmiCasSerializer xmiCasSerializer = new XmiCasSerializer(cas.getTypeSystem());
    boolean caughtException = false;
    try {
        xmiCasSerializer.serialize(cas, xmlSerializer.getContentHandler());
    } catch (SAXParseException e) {
        caughtException = true;
    }
    out.close();
    assertTrue("XMI serialization of document text with bad XML 1.0 char should throw exception", caughtException);
    // but when XML 1.1 output is being generated, don't fail on control characters which are valid
    // in 1.1.
    if (XML1_1_SUPPORTED) {
        out = new FileOutputStream(outputFile);
        try {
            XMLSerializer xml11Serializer = new XMLSerializer(out);
            xml11Serializer.setOutputProperty(OutputKeys.VERSION, "1.1");
            xmiCasSerializer.serialize(cas, xml11Serializer.getContentHandler());
        } finally {
            out.close();
        }
        outputFile.delete();
        out = new FileOutputStream(outputFile);
        CasIOUtils.save(cas, out, SerialFormat.XMI_1_1);
    }
}

