@Test
public void testMultithreadedIterator() {
    setupFSs();
    final FSIndex<FeatureStructure> bagIndex = cas.getIndexRepository().getIndex(CASTestSetup.ANNOT_BAG_INDEX);
    final FSIndex<FeatureStructure> setIndex = cas.getIndexRepository().getIndex(CASTestSetup.ANNOT_SET_INDEX);
    final FSIndex<FeatureStructure> sortedIndex = cas.getIndexRepository().getIndex(CASTestSetup.ANNOT_SORT_INDEX);
    int numberOfCores = Math.min(50, Runtime.getRuntime().availableProcessors() * 5);
    System.out.println("test multicore iterator with " + numberOfCores + " threads");
    MultiThreadUtils.ThreadM[] threads = new MultiThreadUtils.ThreadM[numberOfCores];
    // trick to get a return value in a parameter
    final Throwable[] tthrowable = new Throwable[1];
    tthrowable[0] = null;
    for (int i = 0; i < numberOfCores; i++) {
        final int finalI = i;
        threads[i] = new MultiThreadUtils.ThreadM() {

            @Override
            public void run() {
                try {
                    while (true) {
                        if (!MultiThreadUtils.wait4go(this)) {
                            break;
                        }
                        setIteratorWithoutMods(setIndex, finalI);
                        sortedIteratorWithoutMods(sortedIndex);
                        bagIteratorWithoutMods(bagIndex);
                    }
                } catch (Throwable e) {
                    tthrowable[0] = e;
                    e.printStackTrace();
                    throw new RuntimeException(e);
                }
            }
        };
        threads[i].start();
    }
    for (int r = 0; r < 10; r++) {
        MultiThreadUtils.kickOffThreads(threads);
        MultiThreadUtils.waitForAllReady(threads);
        for (int i = 0; i < numberOfCores; i++) {
            if (tthrowable[0] != null) {
                assertTrue(false);
            }
            if (tthrowable[0] != null) {
                assertTrue(false);
            }
        }
    }
    MultiThreadUtils.terminateThreads(threads);
}

