        engAnnot = engIt.get();
        gerAnnot = gerIt.get();
        frAnnot = frIt.get();
        assertThat(engAnnot.getType().getName()).isEqualTo(annotationType.getName());
        assertThat(engAnnot.getCoveredText()).isEqualTo(("this"));
        assertThat(frAnnot.getType().getName()).isEqualTo(annotationType.getName());
