@Test
public void testSet() {
    StringArrayFS array = cas.createStringArrayFS(0);
    assertTrue(array != null);
    assertTrue(array.size() == 0);
    //
    assertThatExceptionOfType(ArrayIndexOutOfBoundsException.class).isThrownBy(() -> array.get(0));
    StringArrayFS array2 = cas.createStringArrayFS(3);
    array2.set(0, "1");
    array2.set(1, "2");
    array2.set(2, "3");
    String[] stringArray = array2.toStringArray();
    assertTrue(array2.size() == stringArray.length);
    for (int i = 0; i < stringArray.length; i++) {
        assertTrue(stringArray[i].equals(array2.get(i)));
    }
    //
    assertThatExceptionOfType(ArrayIndexOutOfBoundsException.class).as(//
    "Cannot set value at index < 0").isThrownBy(() -> array2.set(-1, "1"));
    //
    assertThatExceptionOfType(ArrayIndexOutOfBoundsException.class).as(//
    "Cannot set value at index beyond end of the array").isThrownBy(() -> array2.set(4, "1"));
    assertTrue(array2.get(0).equals("1"));
    assertTrue(array2.get(1).equals("2"));
    assertTrue(array2.get(2).equals("3"));
    //
    assertThatExceptionOfType(ArrayIndexOutOfBoundsException.class).as(//
    "Cannot get value at index < 0").isThrownBy(() -> array2.get(-1));
    //
    assertThatExceptionOfType(ArrayIndexOutOfBoundsException.class).as(//
    "Cannot get value at index beyond end of the array").isThrownBy(() -> array2.get(4));
    //
    assertThatExceptionOfType(CASRuntimeException.class).as("We can't create arrays smaller than 0").isThrownBy(//
    () -> cas.createStringArrayFS(-1)).extracting(//
    CASRuntimeException::getMessageKey).isEqualTo(CASRuntimeException.ILLEGAL_ARRAY_SIZE);
}

@Test
public void testToArray() {
    // From CAS array to Java array.
    StringArrayFS array = cas.createStringArrayFS(3);
    String[] fsArray = array.toArray();
    for (int i = 0; i < 3; i++) {
        assertTrue(fsArray[i] == null);
    }
    array.set(0, "1");
    array.set(1, "2");
    array.set(2, "3");
    fsArray = array.toArray();
    assertTrue(fsArray.length == 3);
    assertTrue(fsArray[0].equals("1"));
    assertTrue(fsArray[1].equals("2"));
    assertTrue(fsArray[2].equals("3"));
    // From Java array to CAS array.
    array = cas.createStringArrayFS(3);
    assertTrue(array.get(0) == null);
    assertTrue(array.get(1) == null);
    assertTrue(array.get(2) == null);
    for (int i = 0; i < 3; i++) {
        array.set(i, fsArray[i]);
    }
    assertTrue(array.get(0).equals("1"));
    assertTrue(array.get(1).equals("2"));
    assertTrue(array.get(2).equals("3"));
    array.set(0, null);
    assertTrue(array.get(0) == null);
}

