    primitiveDesc.getMetaData().getConfigurationParameterDeclarations().setConfigurationParameters(p1);
    primitiveDesc.getMetaData().getConfigurationParameterSettings().setParameterSettings(new NameValuePair[] { new NameValuePair_impl("StringParam", "Test1") });
    // create pool
