@Test
void testRebalance() {
    // 100 elements, require 256 table (128 * .66 = 85)
    for (int i = 1; i < 101; i++) {
        ihm.put(i, i * 10);
    }
    // have 100 elements, remove 100 elements
    for (int i = 1; i < 101; i++) {
        assertThat((int) ihm.remove(i)).isEqualTo(i * 10);
    }
    assertThat(ihm.size()).isZero();
    assertThat(ihm.getCapacity()).isEqualTo(64);
    for (int i = 1; i < 101 + REBAL; i++) {
        // add different keys, so may use some new slots
        ihm.put(i + 100, i * 10);
    }
    // because above are different adds, likely into
    assertThat(ihm.getCapacity()).isEqualTo(256);
    // non-removed positions
    // have 100 elements, remove 100 elements
    for (int i = 1; i < 101 + REBAL; i++) {
        assertThat((int) ihm.remove(i + 100)).isEqualTo(i * 10);
    }
    assertThat(ihm.getCapacity()).isEqualTo(64);
}

@Test
void testRandom() {
    int countAdd = 0;
    int dupsA = 0;
    int notPres = 0;
    int countRmv = 0;
    // -6616473831883690L;
    long // -6616473831883690L;
    seed = new Random().nextLong();
    System.out.println("Random seed for Int2ObjHashMapTest: " + seed);
    Random r = new Random(seed);
    for (int i = 1; i < 1024 * 512; i++) {
        int k = i & 1024 - 1;
        if (k == 0)
            continue;
        if (r.nextInt(3) > 0) {
            int sz = ihm.size();
            if (ihm.put(k, -k) == null) {
                countAdd++;
                assertThat(ihm.size()).isEqualTo(sz + 1);
            } else {
                dupsA++;
            }
        } else {
            int sz = ihm.size();
            if (ihm.remove(k) != null) {
                countRmv++;
                assertThat(ihm.size()).isEqualTo(sz - 1);
            } else {
                notPres++;
            }
        }
    }
    System.out.format("%s testRandom added: %,d dups: %,d rmvd: %,d notPres: %,d, size: %d%n", this.getClass().getName(), countAdd, dupsA, countRmv, notPres, ihm.size());
    assertThat(ihm.size()).isEqualTo(countAdd - countRmv);
}

