            // System.out.print("m");
        }
        JFSIndexRepository jir = jcas.getJFSIndexRepository();
        FSIterator<Root> it = jir.<Root>getIndex("all", Root.type).iterator();
        // System.out.print("\nTesting Random: ");
        while (it.isValid()) {
            root1.test(it.get());
            // System.out.print("t");
            it.moveToNext();
        }
    } catch (Exception e) {
        JUnitExtension.handleException(e);
    }
}

