@Test
void thatMultiThreadedResolvingRandomComplexImportScenarioWithSingleResourceManagerWorks() throws Exception {
    final int maxThreadCount = 10;
    final int maxTsCount = 10;
    final int maxPasses = 5;
    final int maxImportsPerPass = 3;
    final int maxTypesPerTypeSystem = 10;
    final int maxFeaturesPerType = 10;
    final int runs = 250;
    log.info("Running {} incrementally growing import test scenarios. This may take a moment...", runs);
    log.info("Max. parallel resolving threads : {}", maxThreadCount);
    log.info("Max. type systems               : {}", maxTsCount);
    log.info("Max. import generation passes   : {}", maxPasses);
    log.info("Max. imports generated per pass : {}", maxImportsPerPass);
    log.info("Max. types per type system      : {}", maxTypesPerTypeSystem);
    log.info("Max. features per type          : {}", maxFeaturesPerType);
    long typeSystemsProcessed = 0;
    long totalDurationAllRuns = 0;
    for (int i = 0; i < runs; i++) {
        final int threadCount = ((i * maxThreadCount) / runs) + 1;
        final int tsCount = ((i * maxTsCount) / runs) + 1;
        final int passes = ((i * maxPasses) / runs) + 1;
        final int importsPerPass = ((i * maxImportsPerPass) / runs) + 1;
        final int typesPerTypeSystem = ((i * maxTypesPerTypeSystem) / runs) + 1;
        final int featuresPerType = ((i * maxFeaturesPerType) / runs) + 1;
        log.debug("Run {}: Threads: {}  TS: {}  types-per-TS: {}  features-per-type: {}  " + "passes: {}  imports-per-pass: {}", i + 1, threadCount, tsCount, typesPerTypeSystem, featuresPerType, passes, importsPerPass);
        List<Entry<File, Set<TypeDescription>>> data = prepareComplexImportScenario(tsCount, typesPerTypeSystem, featuresPerType, passes, importsPerPass);
        long totalDurationThisRun = 0;
        ResourceManager resMgr = newDefaultResourceManager();
        List<ResolveImportsRunner> runners = new ArrayList<>();
        for (Entry<File, Set<TypeDescription>> e : data) {
            runners.add(new ResolveImportsRunner(resMgr, e.getKey(), e.getValue()));
        }
        List<ResolveImportsRunner> finishedRunners = new ArrayList<>();
        ExecutorService executorService = Executors.newFixedThreadPool(threadCount);
        for (Future<ResolveImportsRunner> runner : executorService.invokeAll(runners)) {
            finishedRunners.add(runner.get());
        }
        //
        assertThat(executorService.shutdownNow()).as(//
        "No remaining runners when shutting down the executor service").isEmpty();
        //
        assertThat(finishedRunners).as(//
        "All runners made it to the finishing line").hasSameSizeAs(runners);
        for (ResolveImportsRunner runner : finishedRunners) {
            totalDurationThisRun += runner.duration;
            String[] expectedUniqueTypeNames = //
            runner.expectedTypes.stream().map(//
            TypeDescription::getName).//
            sorted().//
            distinct().toArray(String[]::new);
            String[] actualUniqueTypeNames = //
            Stream.of(runner.descriptor.getTypes()).map(//
            TypeDescription::getName).//
            sorted().//
            distinct().toArray(String[]::new);
            log.debug("Types: {}  unique types: {} ({}ms)", runner.descriptor.getTypes().length, actualUniqueTypeNames.length, runner.duration);
            assertThat(runner.descriptor.getTypes()).// Note that in the general case, there may still be duplicates if the same type is
            // declared in more than one type system description. However, the scenario
            // generator does not cover this case, so we can make this assertion here to check
            // if the deduplication during resolving works
            as("Deduplication of same type reachable through different paths").hasSameSizeAs(actualUniqueTypeNames);
            //
            assertThat(actualUniqueTypeNames).as("Mismatch in %s", //
            runner.descriptorFile).containsExactly(expectedUniqueTypeNames);
            //
            assertThat(runner.descriptor.getTypes()).as("Mismatch in %s", //
            runner.descriptorFile).containsAll(runner.expectedTypes);
        }
        log.debug("Total time spent resolving imports in {} type systems: {}ms", data.size(), totalDurationThisRun);
        totalDurationAllRuns += totalDurationThisRun;
        typeSystemsProcessed += data.size();
    }
    log.info("Average import resolving time in {} type systems: {}ms", typeSystemsProcessed, totalDurationAllRuns / (double) typeSystemsProcessed);
    log.info("Note that the multi-threaded average is higher than a single-threaded average " + "because multiple threads may wait in parallel for a descriptor to be parsed " + "and each of them will count the waiting time towards their individual duration.");
}

