    // test import from programatically created TypeSystemDescription
    Import_impl[] imports = { new Import_impl() };
    imports[0].setSourceUrl(url);
    imports[0].setLocation("TypeSystemImportedByLocation.xml");
    TypeSystemDescription typeSystemDescription = getResourceSpecifierFactory().createTypeSystemDescription();
    typeSystemDescription.setImports(imports);
    TypeSystemDescription typeSystemWithResolvedImports = (TypeSystemDescription) typeSystemDescription.clone();
    typeSystemWithResolvedImports.resolveImports(resMgr);
    assertThat(typeSystemWithResolvedImports.getTypes()).isNotEmpty();
    // test that importing the same descriptor twice (using the same ResourceManager) caches
    // the result of the first import and does not create new objects
    TypeSystemDescription typeSystemDescription2 = getResourceSpecifierFactory().createTypeSystemDescription();
    Import_impl[] imports2 = { new Import_impl() };
    imports2[0].setSourceUrl(url);
    imports2[0].setLocation("TypeSystemImportedByLocation.xml");
    typeSystemDescription2.setImports(imports2);
    TypeSystemDescription typeSystemWithResolvedImports2 = (TypeSystemDescription) typeSystemDescription2.clone();
    typeSystemWithResolvedImports2.resolveImports(resMgr);
    assertThat(typeSystemWithResolvedImports.getTypes()).as("Resolved types in second type system are equal to the ones the first").containsExactlyElementsOf(asList(typeSystemWithResolvedImports2.getTypes()));
    assertThat(typeSystemWithResolvedImports.getTypes()).as("Types are NOT the same as in the first because that could allow cache pollution").usingElementComparator((a, b) -> identityHashCode(a) - identityHashCode(b)).doesNotContainAnyElementsOf(asList(typeSystemWithResolvedImports2.getTypes()));
}

@Test
void testBuildFromXmlElement() throws Exception {
    var docBuilderFactory = DocumentBuilderFactory.newInstance();
    var docBuilder = docBuilderFactory.newDocumentBuilder();
    // name import
    var importXml = "<import name=\"this.is.a.test\"/>";
    var importDoc = docBuilder.parse(new ByteArrayInputStream(importXml.getBytes(UTF_8)));
    var importObj = new Import_impl();
    importObj.buildFromXMLElement(importDoc.getDocumentElement(), null);
