@Test
void testIsLoggable() throws Exception {
    // create logger
    org.apache.uima.util.Logger uimaLogger = null;
    try {
        uimaLogger = Log4jLogger_impl.getInstance();
    } catch (Exception e) {
        System.err.println(e);
        e.printStackTrace(System.err);
        throw e;
    }
    var classLogger = Log4jLogger_impl.getInstance(this.getClass());
    assertThat(uimaLogger).isNotNull();
    assertThat(classLogger).isNotNull();
    var log4jLogger = org.apache.logging.log4j.LogManager.getLogger("org.apache.uima");
    while (log4jLogger.getLevel() == null) {
        log4jLogger = LogManager.getRootLogger();
    }
    // log4jLogger.getLevel().toString();
    var key = "INFO";
    // logLevels.get(key); // doesn't work
    var defaultLogLevel = Level.INFO;
    assertThat(defaultLogLevel).isNotNull();
    // check message logging for root logger based on default log level
    assertThat(uimaLogger.isLoggable(Level.ALL)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.ALL));
    assertThat(uimaLogger.isLoggable(Level.FINEST)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.FINEST));
    assertThat(uimaLogger.isLoggable(Level.FINER)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.FINER));
    assertThat(uimaLogger.isLoggable(Level.FINE)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.FINE));
    assertThat(uimaLogger.isLoggable(Level.CONFIG)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.CONFIG));
    assertThat(uimaLogger.isLoggable(Level.INFO)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.INFO));
    assertThat(uimaLogger.isLoggable(Level.WARNING)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.WARNING));
    assertThat(uimaLogger.isLoggable(Level.SEVERE)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.SEVERE));
    assertThat(uimaLogger.isLoggable(Level.OFF)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.OFF));
    // check message logging for class logger based on default log level
    assertThat(classLogger.isLoggable(Level.ALL)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.ALL));
    assertThat(classLogger.isLoggable(Level.FINEST)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.FINEST));
    assertThat(classLogger.isLoggable(Level.FINER)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.FINER));
    assertThat(classLogger.isLoggable(Level.FINE)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.FINE));
    assertThat(classLogger.isLoggable(Level.CONFIG)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.CONFIG));
    assertThat(classLogger.isLoggable(Level.INFO)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.INFO));
    assertThat(classLogger.isLoggable(Level.WARNING)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.WARNING));
    assertThat(classLogger.isLoggable(Level.SEVERE)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.SEVERE));
    assertThat(classLogger.isLoggable(Level.OFF)).isEqualTo(defaultLogLevel.isGreaterOrEqual(Level.OFF));
    // reset class logger level to OFF
    // Logger.getLogger(this.getClass().getName()).setLevel(java.util.logging.Level.OFF);
    classLogger.setLevel(Level.OFF);
    assertThat(classLogger.isLoggable(Level.ALL)).isFalse();
    assertThat(classLogger.isLoggable(Level.FINEST)).isFalse();
    assertThat(classLogger.isLoggable(Level.FINER)).isFalse();
    assertThat(classLogger.isLoggable(Level.FINE)).isFalse();
    assertThat(classLogger.isLoggable(Level.CONFIG)).isFalse();
    assertThat(classLogger.isLoggable(Level.INFO)).isFalse();
    assertThat(classLogger.isLoggable(Level.WARNING)).isFalse();
    assertThat(classLogger.isLoggable(Level.SEVERE)).isFalse();
    assertThat(classLogger.isLoggable(Level.OFF)).isTrue();
    // reset class logger level to ALL
    // Logger.getLogger(this.getClass().getName()).setLevel(java.util.logging.Level.ALL);
    classLogger.setLevel(Level.ALL);
    assertThat(classLogger.isLoggable(Level.ALL)).isTrue();
    assertThat(classLogger.isLoggable(Level.FINEST)).isTrue();
    assertThat(classLogger.isLoggable(Level.FINER)).isTrue();
    assertThat(classLogger.isLoggable(Level.FINE)).isTrue();
    assertThat(classLogger.isLoggable(Level.CONFIG)).isTrue();
    assertThat(classLogger.isLoggable(Level.INFO)).isTrue();
    assertThat(classLogger.isLoggable(Level.WARNING)).isTrue();
    assertThat(classLogger.isLoggable(Level.SEVERE)).isTrue();
    assertThat(classLogger.isLoggable(Level.OFF)).isTrue();
    // reset class logger level to WARNING
    // Logger.getLogger(this.getClass().getName()).setLevel(java.util.logging.Level.WARNING);
    classLogger.setLevel(Level.WARNING);
    assertThat(classLogger.isLoggable(Level.ALL)).isFalse();
    assertThat(classLogger.isLoggable(Level.FINEST)).isFalse();
    assertThat(classLogger.isLoggable(Level.FINER)).isFalse();
    assertThat(classLogger.isLoggable(Level.FINE)).isFalse();
    assertThat(classLogger.isLoggable(Level.CONFIG)).isFalse();
    assertThat(classLogger.isLoggable(Level.INFO)).isFalse();
    assertThat(classLogger.isLoggable(Level.WARNING)).isTrue();
    assertThat(classLogger.isLoggable(Level.SEVERE)).isTrue();
    assertThat(classLogger.isLoggable(Level.OFF)).isTrue();
    // reset log level to default log level
    classLogger.setLevel(defaultLogLevel);
}

