/**
 * Create multiple processors which have to process multiple documents
 *
 * @throws Exception
 *           -
 */
@Test
public void testCasPool() throws Exception {
    // process 100 documents and multiple threads
    int documentCount = 100;
    int threadCount = 5;
    // setup CPM to process 100 documents
    CollectionProcessingEngine cpe = setupCpm(documentCount, threadCount);
    // create and register a status callback listener
    TestStatusCallbackListener listener = new TestStatusCallbackListener() {

        TypeSystem sts = null;

        @Override
        public void entityProcessComplete(CAS aCas, EntityProcessStatus aStatus) {
            super.entityProcessComplete(aCas, aStatus);
            if (sts == null) {
                sts = aCas.getTypeSystem();
            } else {
                Assert.assertTrue(sts == aCas.getTypeSystem());
            }
        }
    };
    cpe.addStatusCallbackListener(listener);
    // run CPM
    cpe.process();
    // wait until CPM has finished
    while (!listener.isFinished()) {
        Thread.sleep(5);
    }
    // check if CasConsumer was called
    Assert.assertEquals("StatusCallbackListener", documentCount, listener.getEntityProcessCompleteCount());
    Assert.assertEquals("CasConsumer process Count", documentCount, FunctionErrorStore.getCasConsumerProcessCount());
    Assert.assertEquals("Annotator process count", documentCount, FunctionErrorStore.getAnnotatorProcessCount());
    Assert.assertEquals("Collection reader getNext count", documentCount, FunctionErrorStore.getCollectionReaderGetNextCount());
    Assert.assertEquals("number of annoators", threadCount, FunctionErrorStore.getAnnotatorCount());
}

