 * the cpm should regular finish after processing all documents. No error and no abort should
 * occur.
 *
 * @throws Exception
 *           -
 */
@Test
public void testProcessWithAnnotatorProcessException() throws Exception {
    // number of document to process
    int documentCount = 20;
    // the sequence in which errors are produced
    int exceptionSequence = 4;
    ManageOutputDevice.setAllSystemOutputToNirvana();
    // setup CPM
    CollectionProcessingEngine cpe = setupCpm(documentCount, "AnnotatorProcessException", exceptionSequence, "process");
    // Create and register a Status Callback Listener
    TestStatusCallbackListener listener = new CollectionReaderStatusCallbackListener(cpe);
    cpe.addStatusCallbackListener(listener);
    cpeProcessNoMsg(cpe, listener);
    ManageOutputDevice.setAllSystemOutputToDefault();
    // check the results, if everything worked as expected
    assertEquals("The cpm is still working or the collectionProcessComplete-method of the listener was not called.", true, listener.isFinished());
    assertEquals("The cpm propably didn't finish correctly! The aborted method of the listener was called.", false, listener.isAborted());
    assertEquals("There are not as much exceptions as expected! ", countExceptions(documentCount, exceptionSequence), FunctionErrorStore.getCount());
}

